#include <string>
#include <algorithm>
using namespace std;

bool isPalindrome(const string& s, int left, int right) {
    while (left < right) {
        if (s[left++] != s[right--]) {
            return false;
        }
    }
    return true;
}

string longestPalindrome(string s) {
    int n = s.length();
    if (n < 2) return s;
    string longest = "";

    for (int i = 0; i < n; ++i) {
        for (int j = i; j < n; ++j) {
            if (isPalindrome(s, i, j)) {
                if (j - i + 1 > longest.length()) {
                    longest = s.substr(i, j - i + 1);
                }
            }
        }
    }
    return longest;
}

