class Solution:
    def longestPalindrome(self, s: str) -> str:
        n = len(s)
        if n < 2: return s

        start, max_len = 0, 1

        def is_palindrome(sub):
            return sub == sub[::-1]

        for i in range(n):
            for j in range(i, n):
                substring = s[i:j+1]
                if is_palindrome(substring):
                    if len(substring) > max_len:
                        max_len = len(substring)
                        start = i

        return s[start:start + max_len]

